import { describe, expect, it } from "vitest";
import { shout } from "./volume.js";

describe("shout", () => {
  it("uppercases lowercase text", () => {
    expect(shout("hello")).toBe("HELLO");
  });

  it("uppercases mixed-case text", () => {
    expect(shout("Hello, World!")).toBe("HELLO, WORLD!");
  });

  it("leaves already uppercase text unchanged", () => {
    expect(shout("HELLO")).toBe("HELLO");
  });

  it("handles an empty string", () => {
    expect(shout("")).toBe("");
  });
});

